  sit("A hospitalized 4-year-old is afraid of an injection. How can the nurse use play to help?", "Let the child act out the procedure with a doctor and nurse's kit to understand it and reduce fear and anxiety", ["Avoid explaining so the child will not be anxious", "Restrict all play during hospitalization", "Use play only as a reward after the procedure"], "Importance of play in MCN: reduces fear and anxiety during hospitalization and helps children understand procedures through play.");
  sit("A group of 7-year-olds play a game together with rules, shared goals and assigned roles. Which type of play is this?", "Cooperative play", ["Parallel play", "Solitary play", "Onlooker play"], "Cooperative play - school-age children: they play together with rules, shared goals and assigned roles.");
  pg = "p.9";
  sit("A nurse is choosing a toy for a 2-year-old. Which are the safety concerns for toddler toys?", "Small pieces that can be swallowed, lead-based paint and flammable materials", ["Toy being too colorful", "Toy being too big to share", "Toy needing two players"], "Danger of: breaking a toy and ingesting small pieces; ingesting lead from lead-based paint; being burned by potentially flammable toys.");
  pg = "p.10";
  sit("A 10-year-old wants a new hobby. Which suggested play fits a 9 to 12 year old?", "Model kits, chess and handicrafts", ["Push-pull toys and pounding toys", "Rocking horse", "Finger paints and sandbox toys"], "Suggested play for 9 to 12: handicrafts of all kinds, model kits, pottery clay, hobbies, collection; archery, dart games, chess, jigsaw puzzles; science toys, magic sets.");

